#nullable enable
using System;
using System.IO;
using System.Reflection;
using System.Text;
using Xml.Schema.Linq.CodeGen.Extensions;

namespace Xml.Schema.Linq.CodeGen
{
    internal static class PragmaHelper
    {
        /// <summary>
        /// Changes the default auto-generated comment at the beginning of C# source code files, to include the version of the tool used to generate the code.
        /// <para>If both <paramref name="toolVersion"/> and <paramref name="assembly"/> are null, then the <see cref="Assembly.GetCallingAssembly"/> method is used to determine the version.</para>
        /// </summary>
        /// <param name="writer"></param>
        /// <param name="toolVersion"></param>
        /// <param name="assembly"></param>
        /// <exception cref="ArgumentNullException"></exception>
        public static void UpdateAutoGeneratedComment(this StringWriter writer, string? toolVersion = null, Assembly? assembly = null)
        {
            if (writer == null) throw new ArgumentNullException(nameof(writer));
            
            UpdateAutoGeneratedComment(writer.GetStringBuilder(), toolVersion, assembly);
        }

        public static void UpdateAutoGeneratedComment(this StringBuilder builder, string? toolVersion = null, Assembly? assembly = null)
        {
            if (builder == null) throw new ArgumentNullException(nameof(builder));
            if (builder.Length == 0) return;

            toolVersion ??= (assembly ?? Assembly.GetCallingAssembly()).GetAssemblyVersion();
            bool withPrefix = false;
            string replacementLine = $"//     LinqToXsd Version: {toolVersion}";

            int runtimeVersionIndex = builder.IndexOf("Runtime Version:");
            if (runtimeVersionIndex < 0)
            {
                runtimeVersionIndex = builder.IndexOf("This code was generated by a tool.");
                withPrefix = true;
            }

            if (withPrefix) 
                replacementLine = $"//     This code was generated by a tool.{Environment.NewLine}" + replacementLine;

            int lineStart = runtimeVersionIndex;
            while (lineStart > 0 && builder[lineStart - 1] != '\n' && builder[lineStart - 1] != '\r') {
                lineStart--;
            }

            int lineEnd = runtimeVersionIndex;
            while (lineEnd < builder.Length && builder[lineEnd] != '\r' && builder[lineEnd] != '\n') {
                lineEnd++;
            }

            builder.Remove(lineStart, lineEnd - lineStart);
            builder.Insert(lineStart, replacementLine);
        }

        internal static void InsertFilePragma(this StringWriter writer, string pragma)
        {
            var builder = writer.GetStringBuilder();
            // Insert the pragma on the first blank line, which will be just after the <auto-generated> comment.            
            int blankIndex = builder.IndexOfBlankLine();
            builder.Insert(blankIndex, pragma + "\r\n");
        }
        
        internal static int IndexOfBlankLine(this StringBuilder builder)
        {
            // We look for two chars \n[\r\n], so the stop condition is one less than actual length
            for (int i = 0; i < builder.Length - 1; i++)
            {
                if (builder[i] == '\n')
                {
                    ++i;    // Safe because of the `Length - 1` stop condition
                    if (builder[i] == '\r' || builder[i] == '\n')
                    {
                        return i;
                    }
                }
            }
            return 0;
        }
    }
}